function lineChart(canvas,series,benchmark,dates){const ctx=canvas.getContext('2d');function draw(){let w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);let all=[...series,...benchmark],lo=Math.min(...all),hi=Math.max(...all),pad=(hi-lo)*.12||100;lo-=pad;hi+=pad;let left=58,right=15,top=20,bottom=30;const y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom),x=i=>left+i/(series.length-1)*(w-left-right);ctx.font='10px monospace';for(let i=0;i<=4;i++){let v=lo+(hi-lo)*i/4;ctx.strokeStyle='#cbd2c4';ctx.setLineDash([]);ctx.beginPath();ctx.moveTo(left,y(v));ctx.lineTo(w-right,y(v));ctx.stroke();ctx.fillStyle='#59665f';ctx.fillText(num(v,0),0,y(v)+4)}function plot(s,color,dashed){ctx.beginPath();s.forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));ctx.strokeStyle=color;ctx.lineWidth=2;ctx.setLineDash(dashed?[5,4]:[]);ctx.stroke()}plot(benchmark,'#8d7754',true);plot(series,'#2d715d',false);ctx.setLineDash([]);ctx.fillStyle='#59665f';ctx.fillText(dates[0],left,h-6);ctx.fillText(dates.at(-1),w-85,h-6)}let ro=new ResizeObserver(draw);ro.observe(canvas);draw();cleanups.push(()=>ro.disconnect())}
